<?php
declare(strict_types=1);
$student=PortalEnrollment::ownStudent();
$problem='';
if ($isPost) {
    try { $appId=PortalEnrollment::submit($_POST,In::int($_POST,'application_id')); flash('success','Application submitted. The registrar will review it.'); redirect('myenrollment',['id'=>$appId]); }
    catch (AppError $e) { $problem=$e->getMessage(); }
}
$apps=Db::all('SELECT * FROM sis_portal_enrollments WHERE account_id=? AND student_number=? ORDER BY id DESC',[(int)Auth::centralId(),$student['studentId']]);
$selected=isset($_GET['id']) ? PortalEnrollment::own((int)$_GET['id']) : ($apps[0]??null);
$today=date('Y-m-d');
$periods=Db::all('SELECT * FROM sis_term_calendar WHERE ? BETWEEN enrollment_start AND enrollment_end ORDER BY school_year,FIELD(term,"1st Semester","2nd Semester","3rd Semester","Summer")',[$today]);
$current=PortalEnrollment::currentEnrollment($student);
$returned=$selected && $selected['status']==='RETURNED';
$input=$isPost?$_POST:$_GET;
$legacyPeriod=explode('|',(string)($input['period']??''),2);
$sy=(string)($input['school_year']??($legacyPeriod[0]?:($returned?$selected['school_year']:($periods[0]['school_year']??''))));
$term=(string)($input['term']??($legacyPeriod[1]??($returned?$selected['term']:($periods[0]['term']??''))));
$periodOpen=(bool)array_filter($periods,fn($p)=>$p['school_year']===$sy && $p['term']===$term);
$choices=[];
foreach ($periods as $p) $choices[$p['school_year'].'|'.$p['term']]=PortalEnrollment::placementOptions($student,$p['school_year'],$p['term']);
$options=$choices[$sy.'|'.$term]??['levels'=>[],'sections'=>[]];
$level=(string)($input['requested_year_level']??($returned?($selected['requested_year_level']??''):''));
if ($level==='' && $options['levels']) $level=in_array($current['year_level'],$options['levels'],true)?$current['year_level']:$options['levels'][0];
$preferred=(string)($input['preferred_section_id']??($returned?($selected['preferred_section_doc_id']??''):''));
$checked=($input['check']??'')==='1' || $isPost;
$check=$checked && $periodOpen ? PortalEnrollment::eligibility($student,$sy,$term):null;
$placementError='';
if ($checked && $periodOpen) { try { PortalEnrollment::validatePlacement($student,$sy,$term,$level,$preferred); } catch (AppError $e) { $placementError=$e->getMessage(); } }
$applicationType=((int)substr($sy,0,4)-(int)substr($current['school_year'],0,4))>=2?'Returning student':'Continuing student';
layout_start('Apply for Enrollment'); page_title('Apply for Enrollment','','Confirm your details, submit for registrar review, then follow your assessment and enrollment progress.');
if ($problem) echo '<div class="alert alert-danger" role="alert">'.h($problem).'</div>';
?>
<section class="form-section" aria-labelledby="currentEnrollmentTitle"><h2 class="h6" id="currentEnrollmentTitle">Your current enrollment</h2><p class="mb-2"><strong><?= h($student['studentName']) ?></strong> · Student ID <?= h($student['studentId']) ?></p><dl class="row small mb-2"><dt class="col-sm-3">School year</dt><dd class="col-sm-9"><?= h($current['school_year']?:'Not recorded') ?></dd><dt class="col-sm-3">Semester</dt><dd class="col-sm-9"><?= h($current['term']?:'No confirmed semester recorded yet') ?></dd><dt class="col-sm-3">Year level</dt><dd class="col-sm-9"><?= h($current['year_level']?:'Not recorded') ?></dd><dt class="col-sm-3">Section</dt><dd class="col-sm-9"><?= h($current['section_name']?:'Not recorded') ?></dd></dl><p class="small text-muted mb-0">These details come from your school records. Contact the registrar if something is wrong. Earlier records remain in <a href="<?= url('history',['tab'=>'grades']) ?>">grade history</a> and <a href="<?= url('history',['tab'=>'assessments']) ?>">assessment history</a>.</p></section>
<section class="form-section" aria-labelledby="applyingForTitle"><h2 class="h6" id="applyingForTitle">You are applying for</h2>
<?php if (!$periods): ?><p class="mb-0">Enrollment applications are currently closed.</p><?php else: ?>
<form method="get" id="enrollmentChoiceForm" data-choices="<?= h(json_encode($choices,JSON_THROW_ON_ERROR)) ?>"><input type="hidden" name="r" value="myenrollment"><?php if ($returned): ?><input type="hidden" name="id" value="<?= (int)$selected['id'] ?>"><?php endif; ?><div class="row g-3">
<div class="col-md-6"><label class="form-label" for="applicationSchoolYear">School year</label><select class="form-select" name="school_year" id="applicationSchoolYear" required><?php foreach (array_unique(array_column($periods,'school_year')) as $year): ?><option value="<?= h($year) ?>"<?= $year===$sy?' selected':'' ?>><?= h($year) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="applicationTerm">Semester</label><select class="form-select" name="term" id="applicationTerm" required><?php foreach ($periods as $p): ?><option data-school-year="<?= h($p['school_year']) ?>" value="<?= h($p['term']) ?>"<?= $p['term']===$term && $p['school_year']===$sy?' selected':'' ?><?= $p['school_year']!==$sy?' hidden disabled':'' ?>><?= h($p['term']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="applicationYearLevel">Year level</label><select class="form-select" name="requested_year_level" id="applicationYearLevel" required><option value="">Choose year level</option><?php foreach ($options['levels'] as $yearLevel): ?><option value="<?= h($yearLevel) ?>"<?= $yearLevel===$level?' selected':'' ?>><?= h($yearLevel) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label" for="applicationSection">Preferred section (optional)</label><select class="form-select" name="preferred_section_id" id="applicationSection"><option value="">Registrar will assign my section</option><?php foreach ($options['sections'] as $section) if ($section['year_level']===$level): ?><option value="<?= h($section['id']) ?>"<?= $section['id']===$preferred?' selected':'' ?>><?= h($section['name']) ?></option><?php endif; ?></select><div class="form-text">Subject to registrar approval.</div></div></div><p class="small mt-3 mb-2">Changing semesters keeps your year level. A higher year level is available only after the school’s promotion requirements are met.</p><button class="btn btn-outline-primary" name="check" value="1">Check requirements</button><p class="small text-muted mt-2 mb-0" id="enrollmentChoiceNotice" role="status"><?= !$options['levels']?'No eligible sections are set up for this period. Contact the registrar.':'Choose your details, then click Check requirements.' ?></p></form>
<?php endif; ?>
<?php $activeForPeriod=array_filter($apps,fn($a)=>$a['school_year']===$sy && $a['term']===$term && in_array($a['status'],['PENDING','ACCEPTED'],true)); ?>
<div id="enrollmentCheckedResults">
<?php if ($placementError): ?><div class="alert alert-warning mt-3" role="alert"><?= h($placementError) ?></div><?php endif; ?>
<?php if ($check && !$activeForPeriod): ?><div class="alert alert-<?= $check['can_create']?'success':'warning' ?> mt-3"><strong><?= $check['can_create'] && !$placementError?'Ready for your review':'Action needed before applying' ?></strong><ul class="mb-0 small"><?php foreach ($check['checks'] as $c) if (in_array($c['state'],['BLOCKED','NEEDS_APPROVAL','WARNING'],true)||$c['code']==='grades_complete'): ?><li><?= h($c['message']) ?></li><?php endif; ?></ul></div><?php endif; ?>
<?php if ($activeForPeriod): ?><p class="small mt-3">You already have an application for this period. Follow its progress below.</p><?php endif; ?>
<?php if (!$activeForPeriod && $periodOpen && $check && $check['can_create'] && !$placementError): ?>
<form method="post" class="mt-3" id="enrollmentSubmit" data-confirm="Submit this enrollment request for registrar review? Your preferred section is not yet confirmed."><?= csrf_field() ?><input type="hidden" name="school_year" value="<?= h($sy) ?>"><input type="hidden" name="term" value="<?= h($term) ?>"><input type="hidden" name="requested_year_level" value="<?= h($level) ?>"><input type="hidden" name="preferred_section_id" value="<?= h($preferred) ?>"><?php if ($returned && $selected['school_year']===$sy && $selected['term']===$term): ?><input type="hidden" name="application_id" value="<?= (int)$selected['id'] ?>"><?php endif; ?>
<div class="border rounded p-3 mb-3"><h3 class="h6">Check your request</h3><p class="small mb-1"><strong><?= h($applicationType) ?></strong></p><p class="small mb-1"><strong>Current:</strong> <?= h(implode(' · ',array_filter([$current['year_level'],$current['term'],$current['section_name']]))) ?></p><p class="small mb-1"><strong>Applying for:</strong> <?= h($sy.' · '.$level.' · '.$term) ?></p><p class="small mb-0"><strong>Preferred section:</strong> <?php $preferredChoice=array_values(array_filter($options['sections'],fn($s)=>$s['id']===$preferred)); ?><?= h($preferredChoice[0]['name']??'Registrar will assign') ?></p></div>
<label class="form-label" for="studentEnrollmentNote">Note for the registrar (optional)</label><textarea class="form-control" id="studentEnrollmentNote" name="student_note" maxlength="1000" rows="2"><?= h((string)($_POST['student_note']??($returned?($selected['student_note']??''):''))) ?></textarea><label class="form-check mt-3"><input class="form-check-input" type="checkbox" name="details_confirmed" value="1" required><span class="form-check-label">I checked my current details and the enrollment I am applying for.</span></label><button class="btn btn-primary mt-3">Submit application</button><p class="form-text">The registrar will review your grades, balances and placement, then prepare your assessment. Your current section changes only when enrollment is confirmed.</p></form>
<?php endif; ?></div></section>
<div class="form-section"><h2 class="h6">My applications</h2><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Application</th><th>Applying for</th><th>Progress</th><th></th></tr></thead><tbody><?php foreach ($apps as $a): [$label]=PortalEnrollment::progress($a); ?><tr><td>#<?= (int)$a['id'] ?></td><td><?= h($a['school_year'].' · '.$a['term'].' · '.($a['requested_year_level']?:'Year level to confirm')) ?></td><td><?= h($label) ?></td><td><a href="<?= url('myenrollment',['id'=>$a['id']]) ?>">View</a></td></tr><?php endforeach; if (!$apps): ?><tr><td colspan="4">No enrollment applications yet.</td></tr><?php endif; ?></tbody></table></div></div>
<?php if ($selected): [$label,$step]=PortalEnrollment::progress($selected); ?>
<div class="form-section"><h2 class="h6">Application #<?= (int)$selected['id'] ?> · <?= h($label) ?></h2><ol class="list-unstyled d-flex flex-wrap gap-2 small"><?php foreach (['Application','Registrar Review','Assessment','Payment','Enrolled'] as $i=>$stage): ?><li class="badge rounded-pill <?= $step>=$i+1?'bg-primary-subtle text-primary':'bg-light text-secondary' ?>"<?= $step===$i+1?' aria-current="step"':'' ?>><?= ($i+1).'. '.h($stage) ?></li><?php endforeach; ?></ol><?php $application=$selected; include SIS_ROOT.'/app/views/enrollment_placement.php'; ?><?php if ($selected['review_note']): ?><p><strong>Registrar:</strong> <?= h($selected['review_note']) ?></p><?php endif; ?>
<?php if ($selected['registration_id']): $r=Registration::get((int)$selected['registration_id']); if (PortalEnrollment::published($selected,$r) && Auth::central()->can((int)Auth::centralId(),'portal.assessment.view')): $old=BalanceEnrollment::outstanding($student['studentId'],$selected['school_year'],$selected['term']); ?>
<h3 class="h6 mt-4">Published assessment · <?= h($r['reg_no']) ?></h3><p class="small"><?= h($r['school_year'].' · '.$r['term'].' · '.$r['section_name']) ?></p><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Category / charge</th><th class="text-end">Amount</th></tr></thead><tbody><?php foreach (Db::all('SELECT * FROM sis_registration_items WHERE registration_id=? ORDER BY sort_order,category_name,id',[$r['id']]) as $it): ?><tr><td><?= h($it['category_name'].' · '.$it['label_name']) ?></td><td class="money">₱<?= Money::fmt(Money::cents($it['amount'])) ?></td></tr><?php endforeach; ?><tr class="fw-bold"><td>Current assessment</td><td class="money">₱<?= Money::fmt(Money::cents($r['total_amount'])) ?></td></tr><tr><td>Payments received</td><td class="money">₱<?= Money::fmt(Money::cents($r['amount_paid'])) ?></td></tr><tr><td>Current balance</td><td class="money">₱<?= Money::fmt(Registration::balance($r)) ?></td></tr><tr><td>Previous unpaid balances (on their original accounts)</td><td class="money">₱<?= Money::fmt($old['cents']) ?></td></tr></tbody></table></div><p class="small"><strong>Required payment before enrollment confirmation:</strong> ₱<?= Money::fmt(Money::cents($selected['minimum_payment'])) ?><?= Money::cents($selected['minimum_payment'])===0?' (no minimum payment required by the registrar)':'' ?>. Pay through the school cashier and keep your official receipt. Staff confirm enrollment after the required checks.</p><p class="small">Previous balances are shown separately; they are not charged again on this assessment. <a href="<?= url('my') ?>">View my receipts and account</a>.</p>
<?php endif; endif; ?><h3 class="h6 mt-4">Updates</h3><ul class="small"><?php foreach (Db::all('SELECT * FROM sis_portal_enrollment_events WHERE application_id=? ORDER BY id DESC',[$selected['id']]) as $event): ?><li class="mb-2"><span class="text-muted"><?= h($event['created_at']) ?></span> · <?= h($event['message']) ?></li><?php endforeach; ?></ul></div><?php endif; ?><script src="assets/portal-enrollment.js?v=32" defer></script><?php layout_end();
